INSERT INTO `book_info` VALUES (93, '《围炉夜话》', 'https://img1.baidu.com/it/u=3363823393,2631112139&fm=253&fmt=auto&app=120&f=JPEG?w=680&h=1024', '陈继儒', NULL, 2, 1, 6, 8, '2025-10-10 10:01:09', '《围炉夜话》是陈继儒的经典代表作，兼具思想性与艺术性，被翻译成数十种语言，畅销全球。', '中华书局', '9787586547135', '中华书局', 3, '中华书局印刷分厂', 'https://www.中华书局.com', '2001年第2次印刷', '2001-10-24', 83.06, 88, 0, '2025-12-17 10:01:09', '2025-12-17 10:02:57');
INSERT INTO `book_info` VALUES (94, '《小窗幽记》', 'https://img1.baidu.com/it/u=3363823393,2631112139&fm=253&fmt=auto&app=120&f=JPEG?w=680&h=1024', '蘅塘退士', NULL, 16, 1, 5, 5, '2023-12-31 10:01:09', '《小窗幽记》是蘅塘退士的经典代表作，兼具思想性与艺术性，被翻译成数十种语言，畅销全球。', '中华书局', '9787745597796', '中华书局', 1, '中华书局印刷分厂', 'https://www.中华书局.com', '2012年第1次印刷', '2012-10-26', 32.12, 14, 0, '2025-12-17 10:01:09', '2025-12-17 10:02:57');
INSERT INTO `book_info` VALUES (95, '《唐诗三百首》', 'https://img1.baidu.com/it/u=3363823393,2631112139&fm=253&fmt=auto&app=120&f=JPEG?w=680&h=1024', '朱彝尊', NULL, 7, 1, 6, 8, '2023-12-30 10:01:09', '《唐诗三百首》是朱彝尊的经典代表作，以细腻的笔触和独特的视角，讲述了一段触动人心的故事。', '中华书局', '9787242722423', '中华书局', 5, '中华书局印刷分厂', 'https://www.中华书局.com', '2014年第2次印刷', '2014-05-19', 37.33, 33, 0, '2025-12-17 10:01:09', '2025-12-17 10:02:57');
INSERT INTO `book_info` VALUES (96, '《宋词选》', 'https://img1.baidu.com/it/u=3363823393,2631112139&fm=253&fmt=auto&app=120&f=JPEG?w=680&h=1024', '隋树森', NULL, 16, 1, 5, 9, '2023-02-01 10:01:09', '《宋词选》是隋树森的经典代表作，深刻描绘了人性的复杂与社会的变迁，是文学史上的不朽之作。', '中华书局', '9787303072327', '中华书局', 2, '中华书局印刷分厂', 'https://www.中华书局.com', '2021年第4次印刷', '2021-09-04', 62.01, 70, 0, '2025-12-17 10:01:09', '2025-12-17 10:02:57');
INSERT INTO `book_info` VALUES (97, '《元曲选》', 'https://img1.baidu.com/it/u=3363823393,2631112139&fm=253&fmt=auto&app=120&f=JPEG?w=680&h=1024', '吴楚材', NULL, 13, 1, 2, 8, '2022-09-21 10:01:09', '《元曲选》是吴楚材的经典代表作，兼具思想性与艺术性，被翻译成数十种语言，畅销全球。', '中华书局', '978776803428', '中华书局', 4, '中华书局印刷分厂', 'https://www.中华书局.com', '2021年第3次印刷', '2021-10-06', 76.35, 192, 0, '2025-12-17 10:01:09', '2025-12-17 10:02:57');
INSERT INTO `book_info` VALUES (98, '《古文观止》', 'https://img1.baidu.com/it/u=3363823393,2631112139&fm=253&fmt=auto&app=120&f=JPEG?w=680&h=1024', '司马迁', NULL, 4, 1, 6, 7, '2023-09-02 10:01:09', '《古文观止》是司马迁的经典代表作，以细腻的笔触和独特的视角，讲述了一段触动人心的故事。', '中华书局', '9787442690892', '中华书局', 2, '中华书局印刷分厂', 'https://www.中华书局.com', '2008年第3次印刷', '2008-08-20', 65.56, 158, 0, '2025-12-17 10:01:09', '2025-12-17 10:02:57');
INSERT INTO `book_info` VALUES (99, '《史记》', 'https://img1.baidu.com/it/u=3363823393,2631112139&fm=253&fmt=auto&app=120&f=JPEG?w=680&h=1024', '司马光', NULL, 14, 1, 8, 2, '2025-11-25 10:01:09', '《史记》是司马光的经典代表作，兼具思想性与艺术性，被翻译成数十种语言，畅销全球。', '中华书局', '9787777388340', '中华书局', 1, '中华书局印刷分厂', 'https://www.中华书局.com', '1998年第1次印刷', '1998-06-26', 27.14, 152, 0, '2025-12-17 10:01:09', '2025-12-17 10:02:57');
INSERT INTO `book_info` VALUES (100, '《资治通鉴》', 'https://img1.baidu.com/it/u=3363823393,2631112139&fm=253&fmt=auto&app=120&f=JPEG?w=680&h=1024', '陈寿', NULL, 5, 1, 8, 4, '2025-09-22 10:01:09', '《资治通鉴》是陈寿的经典代表作，以细腻的笔触和独特的视角，讲述了一段触动人心的故事。', '中华书局', '9787364791864', '中华书局', 5, '中华书局印刷分厂', 'https://www.中华书局.com', '2005年第2次印刷', '2005-08-15', 80.76, 65, 0, '2025-12-17 10:01:09', '2025-12-17 10:02:57');
INSERT INTO `book_info` VALUES (101, '百年孤独', 'http://localhost:8089/file/屏幕截图 2025-05-10 231028.png', '哥伦比亚', '111', 10, 3, 3, 3, '2025-12-21 16:40:38', '故事讲述马孔多小镇和布恩地亚家族的兴衰变化与传奇故事，记录了家族命运与百年历史，是重复地叙述相同而荒唐的命运，是拉美国家几百年命运的缩影，独具意味地隐喻着人类“文明”史的建立、发展与终结，在荒凉失落与荒唐可笑中诠释宿命式的轮回。家族中人物名字是相同或相近的，预示着他们拥有殊途同归的孤独命运。《百年孤独》以布恩地亚被捆在树上为开端，以他被蚂蚁吃掉为结束，通过细腻丰富的笔触、大胆自由的想象、魔幻的叙事艺术，讲述布恩地亚家族命运与历史，刻画人物孤独的灵魂与自我救赎，进而体现出个人、家族及全人类的悲悯与孤独情怀，让人们重新思考时代发展与人性变化。', '111', '111-222-333', '111', 11, '111', '111', '1', NULL, NULL, 0, 0, '2025-12-21 16:37:53', '2025-12-21 16:40:38');
INSERT INTO `book_info` VALUES (102, '未命名', NULL, NULL, NULL, 1, 0, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, '2025-12-21 17:24:16', '2025-12-21 17:24:16');

-- ----------------------------
-- Table structure for book_operation_log
-- ----------------------------
DROP TABLE IF EXISTS `book_operation_log`;
CREATE TABLE `book_operation_log`  (
  `log_id` bigint NOT NULL AUTO_INCREMENT COMMENT '日志id',
  `user_id` bigint NOT NULL COMMENT '用户id（关联sys_user表）',
  `book_id` bigint NOT NULL COMMENT '书籍id（关联book_info表）',
  `operation_type` tinyint NOT NULL COMMENT '操作类型：1-预约，2-取消预约，3-借阅，4-续借，5-归还',
  `operation_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '操作时间',
  `operation_desc` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '操作描述',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`log_id`) USING BTREE,
  INDEX `user_id`(`user_id` ASC) USING BTREE,
  INDEX `book_id`(`book_id` ASC) USING BTREE,
  CONSTRAINT `book_operation_log_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `sys_user` (`user_id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `book_operation_log_ibfk_2` FOREIGN KEY (`book_id`) REFERENCES `book_info` (`book_id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 39 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci ROW_FORMAT = DYNAMIC;

